def row(spec):
    row_id, parent, name, local, rank, kind, address, site, sources = spec
    value = {
        "id": row_id,
        "parent": parent,
        "kind": kind,
        "rank": rank,
        "name": name,
        "local": local,
        "country": COUNTRY,
        "sources": list(sources),
    }
    if address:
        value["address"] = [address]
    if site:
        value["site"] = site
    return value


ROWS = {
    parent: [row(spec) for spec in specs]
    for parent, specs in SPECS.items()
}

EXPECTED = {
    parent: len(specs)
    for parent, specs in SPECS.items()
}

ENGLISH_NAMES = {
    item["id"]: item["name"]
    for source_rows in ROWS.values()
    for item in source_rows
}


def clean(source):
    out = {key: value for key, value in source.items()
           if value not in (None, "", [])}
    out.setdefault("checked", CHECKED)
    sources = list(out.get("sources") or [])
    if not sources or len(sources) > 3:
        raise ValueError("%s must cite one to three sources" % out.get("id"))
    if not all(str(url).startswith("http") for url in sources):
        raise ValueError("%s carries a non-URL source" % out.get("id"))
    out["sources"] = sources
    out["cite"] = list(sources)
    if (out.get("address") and
            (not isinstance(out["address"], list) or
             not all(isinstance(line, str) for line in out["address"]))):
        raise ValueError("%s has invalid address" % out.get("id"))
    if out.get("site") and not out["site"].startswith("http"):
        raise ValueError("%s carries a non-URL site" % out.get("id"))
    serialized = json.dumps(out, ensure_ascii=False)
    prohibited = ("\u2013", "\u2014", "\u2018", "\u2019", "\u201c", "\u201d")
    if any(mark in serialized for mark in prohibited):
        raise ValueError("%s contains prohibited punctuation" % out.get("id"))
    return out


def build():
    payloads = {}
    seen = set(ROWS)
    for payload_parent, source_rows in ROWS.items():
        rows = []
        branch_seen = {payload_parent}
        for source in source_rows:
            item = clean(source)
            row_id = item.get("id")
            if not row_id or row_id in seen:
                raise ValueError("duplicate or missing id: %s" % row_id)
            if item.get("parent") not in branch_seen:
                raise ValueError("%s hangs off an unknown branch parent: %s" %
                                 (row_id, item.get("parent")))
            if item.get("kind") not in ("parish", "monastery", "diocese"):
                raise ValueError("%s has unsupported kind: %s" %
                                 (row_id, item.get("kind")))
            if item.get("country") != COUNTRY:
                raise ValueError("%s has invalid country code" % row_id)
            if not item.get("name") or not item.get("local"):
                raise ValueError("%s lacks a name" % row_id)
            seen.add(row_id)
            branch_seen.add(row_id)
            rows.append(item)
        payloads[payload_parent] = {
            "v": 1,
            "parent": payload_parent,
            "country": COUNTRY,
            "rows": rows,
        }
    actual = {parent: len(payload["rows"])
              for parent, payload in payloads.items()}
    if actual != EXPECTED:
        raise ValueError("Italy parent counts changed: %r" % actual)
    row_ids = {item["id"] for source_rows in ROWS.values()
               for item in source_rows}
    if set(ENGLISH_NAMES) != row_ids or len(ENGLISH_NAMES) != sum(EXPECTED.values()):
        raise ValueError("Italy English name coverage changed")
    return payloads


def contributions(payloads=None):
    """Return all rows grouped for the shared directory builders."""
    payloads = payloads or build()
    return {parent: list(payload["rows"])
            for parent, payload in payloads.items()}


def manifest(payloads=None):
    payloads = payloads or build()
    return {
        parent: {
            "url": "/data/directory/%s.v1.json" % parent,
            "country": COUNTRY,
            "count": len(payload["rows"]),
            "merge_required": True,
        }
        for parent, payload in sorted(payloads.items())
    }


def repository_problems(payloads):
    path = ROOT / "data" / "directory.v1.json"
    try:
        directory = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        return ["cannot read %s: %s" % (path.relative_to(ROOT), exc)]
    base_ids = {item.get("id") for item in directory.get("rows", [])}
    errors = []
    for parent in payloads:
        if parent not in base_ids:
            errors.append("missing directory parent: %s" % parent)
    new_ids = {item["id"] for payload in payloads.values()
               for item in payload["rows"]}
    duplicates = sorted(new_ids & base_ids)
    if duplicates:
        errors.append("Italy row IDs already in directory spine: %s" %
                      ", ".join(duplicates))
    return errors


def _source_values(value):
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "source" and isinstance(child, str):
                yield child
            elif key == "sources" and isinstance(child, list):
                for url in child:
                    yield url
            else:
                yield from _source_values(child)
    elif isinstance(value, list):
        for child in value:
            yield from _source_values(child)


def candidate_ledger_problems():
    path = ROOT / "tools" / "directory_candidates" / "italy.json"
    try:
        ledger = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        return ["cannot read %s: %s" % (path.relative_to(ROOT), exc)]
    errors = []
    if ledger.get("countries") != [COUNTRY]:
        errors.append("Italy candidate ledger country changed")
    summary = ledger.get("published_summary") or {}
    if summary.get("by_parent") != EXPECTED:
        errors.append("Italy candidate ledger parent counts do not match rows")
    if summary.get("total") != sum(EXPECTED.values()):
        errors.append("Italy candidate ledger total does not match rows")
    bad_urls = sorted({url for url in _source_values(ledger)
                       if not isinstance(url, str) or not url.startswith("http")})
    if bad_urls:
        errors.append("Italy candidate ledger carries invalid source URLs")
    serialized = json.dumps(ledger, ensure_ascii=False)
    prohibited = ("\u2013", "\u2014", "\u2018", "\u2019", "\u201c", "\u201d")
    if any(mark in serialized for mark in prohibited):
        errors.append("Italy candidate ledger contains prohibited punctuation")
    return errors


def main():
    parser = argparse.ArgumentParser()
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--dump", action="store_true")
    args = parser.parse_args()
    try:
        payloads = build()
        errors = repository_problems(payloads) + candidate_ledger_problems()
    except (OSError, ValueError) as exc:
        print("directory Italy: %s" % exc, file=sys.stderr)
        return 1
    if errors:
        for error in errors:
            print(error, file=sys.stderr)
        return 1
    if args.dump:
        print(json.dumps(payloads, ensure_ascii=False, indent=2))
        return 0
    print("Italy: %d current bodies and worship sites" % sum(EXPECTED.values()))
    for parent, count in sorted(EXPECTED.items()):
        print("%s: %d" % (parent, count))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

